// Parse incoming Noel request and extract endpoint
const input = $input.first().json;
// Webhook wraps POST data in .body property
const requestData = input.body || input;
const endpoint = requestData.endpoint || 'unknown';

return [{
  json: {
    endpoint: endpoint,
    payload: requestData
  }
}];

// Capture Learning - Prepare Notion payload
// ENHANCED with multi-dimensional metadata: Scope, Discipline, Applies To
const payload = $input.first().json.payload;
const now = new Date().toISOString();

// Helper: Create user-friendly summary for Notion (max 2000 chars)
function createNotionSummary(fullContent) {
  if (!fullContent) return '';

  const MAX_LENGTH = 1900; // Safety buffer

  if (fullContent.length <= MAX_LENGTH) {
    return fullContent; // Short enough, use as-is
  }

  // Try to extract WHY and WHAT sections (most important for quick browsing)
  const whyMatch = fullContent.match(/WHY:([\s\S]*?)(?=\n\nWHAT:|$)/i);
  const whatMatch = fullContent.match(/WHAT:([\s\S]*?)(?=\n\nHOW:|$)/i);

  if (whyMatch && whatMatch) {
    const summary = `WHY:${whyMatch[1]}\n\nWHAT:${whatMatch[1]}\n\n[Full content in query results]`;
    if (summary.length <= MAX_LENGTH) {
      return summary;
    }
  }

  // Fallback: Truncate with clear indicator
  return fullContent.substring(0, MAX_LENGTH) + '\n\n... [Truncated - query for full content]';
}

// Build Notion page properties
const properties = {
  'Title': {
    title: [{ text: { content: payload.title || 'Untitled Learning' } }]
  },
  'Type': {
    select: { name: payload.type || 'technical' }
  },
  'Content': {
    rich_text: [{ text: { content: createNotionSummary(payload.content) } }]
  },
  'Context': {
    rich_text: [{ text: { content: createNotionSummary(payload.context) } }]
  },
  'Confidence': {
    select: { name: payload.confidence || 'medium' }
  },
  'Status': {
    select: { name: 'Active' }
  },
  'Timestamp': {
    date: { start: now }
  },
  'Last Modified': {
    date: { start: now }
  },
  'AI Suggested': {
    checkbox: payload.ai_suggested || false
  },
  'AI Accepted': {
    checkbox: false
  }
};

// Add optional fields
if (payload.dev_stream && Array.isArray(payload.dev_stream)) {
  properties['Dev Stream'] = {
    multi_select: payload.dev_stream.map(s => ({ name: s }))
  };
}

if (payload.tags && Array.isArray(payload.tags)) {
  properties['Tags'] = {
    multi_select: payload.tags.map(t => ({ name: t }))
  };
}

if (payload.related_files) {
  properties['Related Files'] = {
    rich_text: [{ text: { content: createNotionSummary(payload.related_files) } }]
  };
}

// NEW: Multi-dimensional metadata
if (payload.scope) {
  properties['Scope'] = {
    select: { name: payload.scope }
  };
}

if (payload.discipline && Array.isArray(payload.discipline)) {
  properties['Discipline'] = {
    multi_select: payload.discipline.map(d => ({ name: d }))
  };
}

if (payload.applies_to) {
  properties['Applies To'] = {
    rich_text: [{ text: { content: createNotionSummary(payload.applies_to) } }]
  };
}

// Project relation (requires page ID)
if (payload.project_id) {
  properties['Project'] = {
    relation: [{ id: payload.project_id }]
  };
}

// Session relation (requires page ID)
if (payload.session_id) {
  properties['Session'] = {
    relation: [{ id: payload.session_id }]
  };
}

return [{
  json: {
    title: payload.title,
    notion_payload: {
      parent: { data_source_id: '2b23d603-acb6-8001-983a-000b5df4e3b7' },
      properties: properties
    }
  }
}];

// Update Learning - Step 1: Query Notion to find page by Title (Learning ID)
const payload = $input.first().json.payload;

// The learning_id IS the title in Notion
// Query by Title field (title property uses different filter syntax)
return [{
  json: {
    query: {
      endpoint: 'query_data_source',
      id: '2b23d603-acb6-8001-983a-000b5df4e3b7'
    },
    body: {
      filter: {
        property: 'Title',
        title: {
          equals: payload.learning_id  // Changed from payload.title
        }
      },
      page_size: 1
    },
    update_payload: payload  // Store for next step
  }
}];

// Start Session - Generate Session ID and prepare Notion payload
const payload = $input.first().json.payload;
const now = new Date().toISOString();

// Generate Session ID: YYYYMMDD-HHMM-project
const date = new Date();
const dateStr = date.toISOString().slice(0,10).replace(/-/g, '');
const timeStr = date.toISOString().slice(11,16).replace(/:/g, '');
const projectSlug = (payload.project || 'unknown').toLowerCase().replace(/[^a-z0-9]/g, '-').slice(0, 20);
const sessionId = `${dateStr}-${timeStr}-${projectSlug}`;

// Build Notion page properties
const properties = {
  'Session ID': {
    title: [{ text: { content: sessionId } }]
  },
  'Goals': {
    rich_text: [{ text: { content: payload.goals || '' } }]
  },
  'Start Time': {
    date: { start: now }
  },
  'Status': {
    select: { name: 'Active' }
  },
  'AI Type': {
    select: { name: payload.ai_type || 'Claude' }
  },
  'Recording Format': {
    select: { name: payload.recording_format || 'asciinema' }
  }
};

// Add recording file path if provided
if (payload.recording_file_path) {
  properties['Recording File Path'] = {
    rich_text: [{ text: { content: payload.recording_file_path } }]
  };
}

// Project relation (requires page ID)
if (payload.project_id) {
  properties['Projects'] = {
    relation: [{ id: payload.project_id }]
  };
}

return [{
  json: {
    session_id: sessionId,
    notion_payload: {
      parent: { data_source_id: '2b43d603-acb6-8064-82f9-000b343a2e1c' },
      properties: properties
    }
  }
}];

// End Session - Step 1: Query Notion to find session by Session ID
